
export type SseEventName =
  | "run.started"
  | "message.started"
  | "assistant.delta"
  | "tool.started"
  | "tool.progress"
  | "tool.completed"
  | "assistant.completed"
  | "run.completed"
  | "error"
  | "done"

export interface SseBasePayload {
  session_id: string
  run_id: string
  /** Monotonically increasing sequence number within the run. */
  seq: number
  /** Unix timestamp (seconds) from the gateway. */
  ts: number
}

/** Emitted immediately after the POST is accepted. */
export interface SseRunStarted extends SseBasePayload {
  user_message: { role: string; content: string }
}

/** Emitted when the assistant model begins generating. */
export interface SseMessageStarted extends SseBasePayload {
  message: { id: string; role: string }
}

/** One streaming token chunk from the model. */
export interface SseAssistantDelta extends SseBasePayload {
  message_id: string
  delta: string
}

/** A tool call has begun executing. */
export interface SseToolStarted extends SseBasePayload {
  message_id: string
  tool_name: string
}

/** Intermediate progress from a long-running tool (or reasoning preview). */
export interface SseToolProgress extends SseBasePayload {
  message_id: string
  tool_name: string
  delta: string
}

/** A tool call has finished. */
export interface SseToolCompleted extends SseBasePayload {
  message_id: string
  tool_name: string
  preview?: string
  args?: unknown
}

/** The assistant has produced its full response for this turn. */
export interface SseAssistantCompleted extends SseBasePayload {
  message_id: string
  /** Full assembled content — use this to replace the streamed delta. */
  content: string
  completed: boolean
  partial: boolean
  interrupted: boolean
  finish_reason?: string | null
  reasoning_content?: string | null
  usage?: SseUsage | null
  /** Images generated by the model this step (image-output models) — data URLs. */
  images?: string[] | null
}

export interface SseUsage {
  input_tokens?: number
  output_tokens?: number
  total_tokens?: number
  cache_read_tokens?: number
  cache_write_tokens?: number
  reasoning_tokens?: number
  /** Estimated spend (USD) for this step/run — host-computed from the catalog. */
  cost?: number
  /** Wall time (ms) of the step/run — powers the last-run summary line. */
  duration_ms?: number
  /** Model that produced this step (per-message metadata). */
  model?: string | null
}

/** The agent turn is fully complete; contains token usage. */
export interface SseRunCompleted extends SseBasePayload {
  message_id: string
  completed: boolean
  messages: unknown[]
  usage: SseUsage | null
  /** Session running spend (USD) — drives the footer's cost readout. */
  session_cost?: number | null
  /** Context window (tokens) of the model that ran — for the % display. */
  context_window?: number | null
}

/** A recoverable or fatal error occurred server-side. */
export interface SseError extends SseBasePayload {
  message: string
}

/** Sentinel event — the server is closing the SSE stream. */
export type SseDone = SseBasePayload

// ---------------------------------------------------------------------------
// Callback interface
// ---------------------------------------------------------------------------

/**
 * Typed callback map consumed by `streamChat()`.
 * All callbacks are optional — only subscribe to what you need.
 */
export interface SseCallbacks {
  onRunStarted?: (event: SseRunStarted) => void
  onMessageStarted?: (event: SseMessageStarted) => void
  onDelta?: (event: SseAssistantDelta) => void
  onToolStarted?: (event: SseToolStarted) => void
  onToolProgress?: (event: SseToolProgress) => void
  onToolCompleted?: (event: SseToolCompleted) => void
  onAssistantCompleted?: (event: SseAssistantCompleted) => void
  onRunCompleted?: (event: SseRunCompleted) => void
  onError?: (event: SseError) => void
  /** Called when the stream closes, regardless of success or failure. */
  onDone?: () => void
}
